import SwiftUI

/// Single source of truth for report wording. Used on screen AND in exported JPGs.
enum ReportCopy {
    static let cdrExplainer =
        "CDR compares the optic cup with the optic disc. Screening is not a diagnosis. CDR alone does not establish glaucoma."
    static let aiDisclaimer =
        "Measurements are generated by an AI model in a research prototype and have not been clinically validated."
}

struct AIDisclaimerView: View {
    var body: some View {
        HStack(alignment: .top, spacing: 8) {
            Image(systemName: "info.circle")
            Text("\(ReportCopy.cdrExplainer) \(ReportCopy.aiDisclaimer)")
                .fixedSize(horizontal: false, vertical: true)
        }
        .font(.caption2)
        .foregroundStyle(.secondary)
    }
}
